const fs=require('fs'),assert=require('assert/strict'),png=require('./scripts/png.cjs');const dir=fs.readFileSync('latest-fringe-sync-path.txt','utf8')+'/',before=JSON.parse(fs.readFileSync(dir+'before.json')),baseline=require('./备份/20261102-side-reference-audit/after.json'),p=structuredClone(before),li=198,changes=[],edits=[];
assert.equal(p.layers[li].name,'前发');assert(p.layers[li].visible&&p.layers[li].sheetIndex===8);
const dec=c=>png.decode(Buffer.from(c.dataURL.split(',')[1],'base64'));function world(c){const im=dec(c),r=c.placement||{x:0,y:0},out=new Uint8Array(40*40*4);assert(!c.placement||(c.placement.w===im.width&&c.placement.h===im.height));for(let y=0;y<im.height;y++)for(let x=0;x<im.width;x++){const xx=x+r.x,yy=y+r.y;if(xx>=0&&xx<40&&yy>=0&&yy<40)out.set(im.data.subarray((y*im.width+x)*4,(y*im.width+x)*4+4),(yy*40+xx)*4);}return out;}
function headY(ai,fi){const key='8_'+ai+'_'+fi,l=p.layers.find(l=>l.sheetIndex===8&&l.name==='head'&&l.frameData[key]);assert(l);const data=world(l.frameData[key]);for(let y=0;y<40;y++)for(let x=0;x<40;x++)if(data[(y*40+x)*4+3])return y;throw Error('empty head');}
for(const [ai,sourceFi]of [[0,2],[1,0]]){const key='8_'+ai+'_'+sourceFi,old=world(baseline.layers[li].frameData[key]),latest=world(before.layers[li].frameData[key]),diff=[];for(let i=0;i<old.length;i+=4)if([0,1,2,3].some(k=>old[i+k]!==latest[i+k]))diff.push({x:i/4%40,y:Math.floor(i/4/40),before:[...old.subarray(i,i+4)],after:[...latest.subarray(i,i+4)]});assert.equal(diff.length,ai===0?18:12);edits.push({direction:p.spriteSheets[8].actions[ai].direction,sourceFrame:sourceFi+1,pixels:diff});for(let fi=0;fi<4;fi++){if(fi===sourceFi)continue;const targetKey='8_'+ai+'_'+fi,c=p.layers[li].frameData[targetKey],im=dec(c),r=c.placement||{x:0,y:0},dy=headY(ai,fi)-headY(ai,sourceFi);let changedPixels=0;for(const e of diff){const x=e.x-r.x,y=e.y+dy-r.y;assert(x>=0&&y>=0&&x<im.width&&y<im.height,'sync would crop');const i=(y*im.width+x)*4,current=[...im.data.subarray(i,i+4)];const expected=current.every((v,k)=>v===e.before[k])||current.every((v,k)=>v===e.after[k]);const equivalentContour=ai===0&&e.x===4&&e.y===17&&current.join(',')==='70,70,94,255'&&e.after[3]===0;assert(expected||equivalentContour,'unexpected target pixel '+targetKey+' '+x+','+y);if(current.some((v,k)=>v!==e.after[k])){im.data.set(e.after,i);changedPixels++;}}
 c.dataURL='data:image/png;base64,'+png.encode(im.width,im.height,im.data).toString('base64');changes.push({layer:li,key:targetKey,headOffset:dy,changedPixels});}}
const recovered=structuredClone(p);for(const c of changes)recovered.layers[c.layer].frameData[c.key]=before.layers[c.layer].frameData[c.key];assert.deepEqual(recovered,before,'only six target fringe cels may change');fs.writeFileSync(dir+'restore-extra-copy.json',JSON.stringify(recovered));assert.deepEqual(JSON.parse(fs.readFileSync(dir+'restore-extra-copy.json')),before);for(const key of ['8_0_2','8_1_0'])assert.deepEqual(p.layers[li].frameData[key],before.layers[li].frameData[key]);
// Outside the user's edit footprint, every per-frame fringe motion pixel stays intact.
for(const change of changes){const ai=Number(change.key.split('_')[1]),edit=edits[ai],a=world(before.layers[li].frameData[change.key]),b=world(p.layers[li].frameData[change.key]),allowed=new Set(edit.pixels.map(e=>(e.y+change.headOffset)*40+e.x));for(let i=0;i<a.length;i+=4)if(!allowed.has(i/4))assert.deepEqual([...b.subarray(i,i+4)],[...a.subarray(i,i+4)]);}
fs.writeFileSync(dir+'candidate.json',JSON.stringify(p));fs.writeFileSync(dir+'diff.json',JSON.stringify({edits,changes},null,2));fs.writeFileSync(dir+'verification.json',JSON.stringify({changes,sourceCelsUnchanged:true,allOtherDataUnchanged:true,existingMotionOutsideEditsUnchanged:true,restoreExtraCopyVerified:true,browserChecked:false},null,2));console.log('PASS',JSON.stringify(changes));
